script:
frappe.ui.form.on('Stripe Customers', {
    invoice: function(frm) {
        if(frm.doc.invoice) {
            frm.clear_table('subscription_items');
            frappe.call({
                method: 'frappe.client.get',
                args: {
                    doctype: 'Sales Invoice',
                    name: frm.doc.invoice
                },
                callback: function(response) {
                    if(response.message) {
                        let sales_invoice = response.message;
                        console.log(sales_invoice)
                        sales_invoice.items.forEach(item => {
                            let child = frm.add_child('subscription_items');
                            child.item_name = item.item_name;
                            child.rate = item.rate;
                        });
                        frm.refresh_field('subscription_items');
                    }
                }
            });
        }
    }
});
